TN.defSec("bones-joints",{"orthopedic-injury-general":{"id":"orthopedic-injury-general","variants":[{"id":"orthopedic-open-fracture","o":{"I":[{"t":"Radiographs of the fractured bone and joints above and below; vascular assessment (pulses, ABI / CTA if circulatory compromise)"}],"L":[{"t":"Type and screen, coagulation studies"}],"S":[{"t":"Analgesia: IV narcotic"}],"A":[{"t":"Cefazolin IV (first-generation cephalosporin); add gentamicin (aminoglycoside) for contaminated wounds","fl":[{"k":"ci","v":"cephalosporin allergy"}]}],"T":[{"t":"Tetanus prophylaxis; thorough irrigation; remove constricting items; cold pack; elevation; splint; reduce deformity with gradual longitudinal traction; NPO"}],"Co":[{"t":"Urgent orthopedic surgery in ED (open fracture, compartment syndrome, irreducible dislocation, circulatory compromise)"}]},"name":"Open fracture / neurovascular compromise / irreducible dislocation (urgent ortho)","level":"I","imp":"Open fracture / limb-threatening orthopedic injury","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۳۵ ساله پس از تصادف با شکستگی باز ساق، نبض دیستال ضعیف.","why":"شستشو، آنتی‌بیوتیک، کزاز، اصلاح گردش خون و جراحی فوری."},{"id":"orthopedic-closed-reduce-splint","o":{"I":[{"t":"Radiographs of the injured bone including joint above and below; comparison films of the unaffected side in children; post-reduction films"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia: IV narcotic (avoid oral analgesics if possible operative lesion); procedural sedation as needed"}],"T":[{"t":"Remove constricting items; cold packs; elevation; reduce with gradual steady longitudinal traction; splint per Table 169-2; NPO until treatment complete"}],"Co":[{"t":"Orthopedic follow-up (outpatient) or admission if co-morbidity, pain control or ambulatory dysfunction (e.g., hip fracture)"}]},"name":"Closed fracture / dislocation — reduce, splint, refer","level":"II","imp":"Closed fracture / dislocation, neurovascularly intact","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زن ۴۵ ساله با دفورمیتی مچ پس از سقوط؛ نبض و حس سالم.","why":"گرافی، آنالژزی، کاهش و اسپلینت و پیگیری ارتوپدی."},{"id":"orthopedic-occult-fracture","o":{"I":[{"t":"Plain films (special views as needed); CT, bone scan or MRI if suspicion persists"}],"L":[{"t":"Not routinely required beyond fixed set"}],"T":[{"t":"Immobilize; cold pack; elevation; analgesia; Salter-Harris I or V in children: immobilize and refer"}],"Co":[{"t":"Orthopedic follow-up"}]},"name":"Suspected occult fracture (negative radiograph, significant tenderness)","level":"III","imp":"Suspected occult fracture (clinically significant tenderness, negative plain film)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۰ ساله با درد شدید لمسی و تحمل وزن مختل ولی گرافی طبیعی.","why":"گرافی منفی رد نمی‌کند؛ ثابت‌سازی و تصویربرداری پیشرفته."}],"ch":"169","name":"Orthopedic injury — initial evaluation and management (fracture / dislocation / open fracture)","name_fa":"آسیب‌های ارتوپدی — ارزیابی و مدیریت اولیه (شکستگی / دررفتگی / شکستگی باز)","cc":["limb-injury","trauma-major","joint-limb-pain"],"keywords":"fracture, dislocation, open fracture, Salter-Harris, splinting, neurovascular exam, occult fracture, reduction, شکستگی, دررفتگی, شکستگی باز, اسپلینت, سالتر هریس","status":"draft","features":["شرح حال دقیق (مکانیسم: سقوط از ارتفاع ← احتمال آسیب ستون فقرات؛ شکستگی خودبه‌خودی ← پاتولوژیک/بدخیمی)؛ لمس سیستماتیک چون درد شکستگی/دررفتگی ممکن است به ناحیه دیگر ارجاع شود","معاینه: تورم، تغییر رنگ، دفورمیتی، ROM فعال و غیرفعال بالا و پایین ضایعه، وضعیت نوروواسکولار و تست حسی‌حرکتی اعصاب محیطی","وضعیت عروقی در اسرع وقت بررسی شود (اصلاح سریع جلوگیری از ایسکمی، از دست رفتن بافت، قطع عضو)","تصویربرداری جایگزین معاینه نیست؛ گرافی منفی شکستگی مهم را رد نمی‌کند (حساسیت لمسی قابل‌توجه، درد با تحمل وزن یا ROM غیرفعال ← شک به شکستگی مخفی؛ CT، bone scan یا MRI)","گرافی مفصل بالا و پایین محل شکستگی؛ در کودکان (مراکز رشد) گرافی مقایسه‌ای سمت سالم","توصیف شکستگی به مشاور: باز/بسته، محل (midshaft، supracondylar، intertrochanteric، intra-articular)، جهت خط شکستگی (عرضی، مایل، مارپیچی، comminuted، segmental، torus، greenstick)، displacement، shortening، angulation، rotational deformity، دررفتگی/subluxation همراه، Salter-Harris","شکستگی باز: اغلب نیاز به جراحی فوری، شستشوی کامل و آنتی‌بیوتیک پروفیلاکسی برای جلوگیری از استئومیلیت و سپسیس؛ کزاز، cefazolin، و aminoglycoside (gentamicin) برای زخم آلوده","Salter-Harris: نوع I و V ممکن است در گرافی دیده نشود؛ بالینی مشکوک، ثابت‌سازی و ارجاع؛ نوع V با نیروی axial loading","نیاز به مشاوره فوری ارتوپدی: شکستگی باز، سندرم کمپارتمان، دررفتگی غیرقابل جا انداختن، اختلال گردش خون، آسیب نیازمند جراحی؛ بستری: بیماری همراه، کنترل درد، اختلال راه رفتن (مثل شکستگی هیپ)","جدول 169-2: وسایل ثابت‌سازی (sling، shoulder immobilizer، long-arm gutter، sugar-tong، short-arm gutter، thumb spica، knee immobilizer، posterior ankle mold، ankle stirrup، hard-soled shoe، walking boot)"],"ddx":[{"n":"Compartment syndrome |","cm":1},{"n":"Neurovascular compromise / open fracture |","cm":1},{"n":"Pathologic fracture |"},{"n":"Occult fracture (negative plain film) |"},{"n":"Ligamentous injury / sprain |"}],"redflags":["نبض/پرفیوژن مختل، پوست باز روی شکستگی، درد خارج از تناسب، دررفتگی غیرقابل جا انداختن"],"guide":"1) کنترل درد و تورم (narcotic IV؛ از داروی خوراکی در ضایعات احتمالاً جراحی پرهیز). 2) خارج کردن حلقه، ساعت، جواهر. 3) کیسه یخ و elevation. 4) NPO تا ارزیابی کامل (ممکن است sedation لازم شود). 5) کاهش دفورمیتی/دررفتگی با کشش تدریجی طولی (در بیمار آرام و sedated بهترین نتیجه)؛ بهبود گردش خون و کاهش خطر تبدیل بسته به باز. 6) اسپلینت مناسب.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 169: Initial Evaluation and Management of Orthopedic Injuries Gregory M. Johnston, pp. 923–928"},"hand-injuries":{"id":"hand-injuries","variants":[{"id":"hand-emergency","o":{"I":[{"t":"Hand and forearm radiographs (radiopaque substances, subcutaneous air, fractures)"}],"L":[{"t":"Type and screen, coagulation studies"}],"S":[{"t":"Analgesia"}],"A":[{"t":"Cefazolin IV for open fracture / contaminated wounds (gentamicin in contaminated wounds)","fl":[{"k":"ci","v":"cephalosporin allergy"}]}],"T":[{"t":"Tetanus prophylaxis; irrigation; elevation; splint; control hemorrhage; amputated part preserved for reimplantation; NPO"}],"Co":[{"t":"Immediate hand surgery consultation (Table 170-1)"}]},"name":"Hand emergency — amputation / compartment syndrome / high-pressure injection / open fracture","level":"I","imp":"Hand emergency requiring immediate hand surgery","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۳۰ ساله با آسیب پرس صنعتی؛ تزریق رنگ به انگشت اشاره، درد زیاد.","why":"ظاهر خوش‌خیم ولی نیاز اورژانس جراحی."},{"id":"hand-tendon-injury","o":{"I":[{"t":"Hand radiographs (avulsion fracture)"}],"L":[{"t":"Not routinely required beyond fixed set"}],"T":[{"t":"Mallet finger: splint DIP in slight hyperextension; boutonniere: splint PIP in extension; tendon laceration: close skin and splint until definitive repair by hand surgeon; tendon rehabilitation follow-up"}],"Co":[{"t":"Delayed hand surgery consultation (Table 170-2)"}]},"name":"Tendon injury (laceration, mallet finger, boutonniere, Jersey finger)","level":"II","imp":"Hand tendon injury","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۴۰ ساله پس از ضربه توپ به نوک انگشت؛ DIP خم و ناتوان در extension.","why":"اسپلینت و ارجاع."},{"id":"hand-dislocation-fracture","o":{"I":[{"t":"Hand radiographs (pre- and post-reduction)"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Digital block anesthesia for reduction; analgesia"}],"T":[{"t":"Reduce dislocation with longitudinal traction and splint (DIP: extension; PIP: 30° flexion; MCP: flexion; thumb IP: 15°–20° flexion; thumb MCP / gamekeeper: thumb spica); phalanx: buddy taping if nondisplaced and stable, gutter splint (MCP 70° flexion, IP extension); metacarpal: ulnar gutter (4th/5th) or radial gutter (2nd/3rd), wrist 20° extension, MCP 70° flexion; reduce if angulated; thumb base (Bennett, Rolando): thumb spica"}],"A":[{"t":"Laceration over metacarpal fracture suggests fight bite — treat as such and consult hand surgery"}],"Co":[{"t":"Hand surgery: irreducible dislocation, complete ligament rupture, intra-articular or unstable fractures"}]},"name":"Finger / thumb dislocation, phalanx or metacarpal fracture","level":"II","imp":"Hand dislocation / fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله با دفورمیتی PIP انگشت پس از ورزش یا شکستگی بوکسور پس از مشت.","why":"کاهش (digital block)، اسپلینت اختصاصی."}],"ch":"170","name":"Hand injuries (tendon, dislocation, fracture, compartment syndrome, high-pressure injection)","name_fa":"آسیب‌های دست (تاندون، دررفتگی، شکستگی، سندرم کمپارتمان، تزریق فشار بالا)","cc":["limb-injury","wound-bite","joint-limb-pain"],"keywords":"hand injury, mallet finger, boutonniere, jersey finger, gamekeeper thumb, boxer fracture, fight bite, high pressure injection, hand compartment syndrome, tendon laceration, آسیب دست, انگشت چکشی, شکستگی بوکسور, گاز انسان, تزریق فشار بالا","status":"draft","features":["عصب مدین: فلکشن مقاوم دیستال شست؛ اولنار: گشودن انگشتان در برابر مقاومت؛ رادیال: حفظ اکستنشن MCP در برابر مقاومت؛ حس: تمایز دو نقطه (< 5 mm)","تاندون: تا 90% پارگی با ROM حفظ‌شده؛ تست در برابر مقاومت و مقایسه با سمت سالم؛ درد در مسیر تاندون ← پارگی نسبی؛ ترمیم فلکسور توسط جراح دست؛ بستن پوست و اسپلینت قابل قبول تا ترمیم قطعی؛ پیگیری و توان‌بخشی همه آسیب‌های تاندون","Mallet finger: پارگی کامل اکستانسور در دیستال فالانکس، DIP خم 40°؛ اسپلینت DIP در hyperextension خفیف","Boutonniere: آسیب سطح پشتی PIP؛ اسپلینت PIP در extension","دررفتگی DIP: معمولاً دورسال؛ digital block؛ کشش طولی، hyperextension خفیف، جا انداختن؛ اسپلینت extension کامل؛ غیرقابل جا ← volar plate/profundus/شکستگی avulsion","دررفتگی PIP: دورسال با پارگی volar plate؛ اسپلینت 30° flexion؛ جانبی: پارگی collateral؛ غیرقابل جا انداختن یا پارگی کامل لیگامان ← جراحی","دررفتگی MCP: دورسال، نیاز به کاهش جراحی (volar plate)؛ اسپلینت MCP در flexion","دررفتگی IP شست: پارگی volar plate، اغلب باز؛ اسپلینت 15° تا 20° flexion؛ MCP شست: thumb spica","Gamekeeper / skier thumb: پارگی UCL؛ زاویه > 30° تا 35° با استرس ابداکشن ← پارگی کامل؛ thumb spica؛ پارگی کامل ← ارجاع جراحی","شکستگی دیستال فالانکس (tuft): همراه نیل‌بد؛ volar یا hairpin splint؛ شکستگی پروگزیمال/میانی بدون جابه‌جایی: buddy taping؛ midshaft عرضی/مارپیچی یا intra-articular: اغلب جراحی؛ gutter splint با MCP 70° flexion","شکستگی متاکارپ (بوکسور MC4/MC5): زخم روی شکستگی ← fight bite؛ زاویه > 20° (MC4)، > 40° (MC5)، > 15° (MC2/3) نیاز به reduction؛ ulnar gutter (MC4/5) یا radial gutter (MC2/3) با مچ 20° extension و MCP 70° flexion؛ شست (Bennett، Rolando): thumb spica","کمپارتمان دست: crush یا extravasation مایع IV/کنتراست؛ درد خارج از تناسب؛ وضعیت استراحت: MCP extension و PIP کمی flexion؛ ادم سفت و درد با کشش پاسیو؛ اورژانس ارتوپدی، تشخیص بالینی","تزریق فشار بالا (> 2000 psi؛ گریس، رنگ، هیدرولیک): ظاهر خوش‌خیم ولی واکنش بافتی شدید ← ایسکمی و قطع عضو؛ گرافی دست و ساعد (ماده رادیواپک و هوای زیرجلدی)؛ ارزیابی جراحی اورژانس","مشاوره فوری جراح دست (جدول 170-1): آسیب عروقی با ایسکمی یا خونریزی کنترل‌نشده، دررفتگی غیرقابل جا، زخم شدیداً آلوده، crush شدید، شکستگی باز، کمپارتمان، تزریق فشار بالا، قطع دست/انگشت","مشاوره تأخیری (جدول 170-2): پارگی تاندون اکستانسور/فلکسور، پارگی FDP (Jersey finger)، mallet finger، آسیب عصب، شکستگی بسته، دررفتگی، لیگامان ناپایدار"],"ddx":[{"n":"Compartment syndrome |","cm":1},{"n":"Open fracture / amputation |","cm":1},{"n":"High-pressure injection injury |","cm":1},{"n":"Fight bite (human bite) |"},{"n":"Tendon laceration |"}],"redflags":["ایسکمی انگشت، درد خارج از تناسب، تزریق فشار بالا، زخم بالای MCP (fight bite)، قطع انگشت"],"guide":"1) معاینه عصبی و تاندونی در برابر مقاومت. 2) گرافی (جسم خارجی رادیواپک). 3) اسپلینت ویژه هر آسیب. 4) مشاوره فوری برای موارد جدول 170-1.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 170: Hand and Wrist Injuries, pp. 929–933"},"wrist-injuries":{"id":"wrist-injuries","variants":[{"id":"wrist-dislocation-emergent","o":{"I":[{"t":"PA and lateral wrist radiographs (loss of \"3 C's\"; \"piece of pie\" on PA, \"spilled teacup\" on lateral)"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia; procedural sedation for reduction"}],"T":[{"t":"Splint; elevation; NPO; neurovascular checks"}],"Co":[{"t":"Emergent orthopedic / hand consultation for closed reduction or surgical repair"}]},"name":"Lunate / perilunate dislocation (emergent consult)","level":"I","imp":"Lunate / perilunate dislocation","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۳۰ ساله پس از سقوط روی دست باز با درد و تورم شدید مچ؛ لترال: spilled teacup.","why":"کاهش بسته یا جراحی اورژانس."},{"id":"wrist-scaphoid-suspected","o":{"I":[{"t":"Wrist radiographs (scaphoid views); advanced imaging may be needed since scaphoid and lunate fractures are often not detected on plain films"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Short-arm thumb spica splint (scaphoid; dorsiflexion with radial deviation); other carpal fractures splinted per Table 170-3"}],"Co":[{"t":"Orthopedic / hand follow-up (scaphoid, lunate, capitate: avascular necrosis risk)"}]},"name":"Suspected scaphoid fracture (snuffbox tenderness) / carpal fracture","level":"II","imp":"Suspected scaphoid fracture / carpal fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۲۵ ساله پس از سقوط روی دست باز با درد snuffbox و گرافی طبیعی.","why":"تشخیص بالینی؛ spica و پیگیری."},{"id":"wrist-distal-radius-fracture","o":{"I":[{"t":"Wrist radiographs (PA / lateral); post-reduction films"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Hematoma block or procedural sedation for reduction; analgesia"}],"T":[{"t":"Closed reduction and sugar-tong splint (Colles, Smith; Barton may need surgery); radial styloid: wrist in mild flexion and ulnar deviation; ulnar styloid: ulnar gutter, wrist neutral, slight ulnar deviation"}],"Co":[{"t":"Orthopedic follow-up; urgent consult for open or unstable injuries"}]},"name":"Distal radius fracture (Colles / Smith / Barton) and styloid fractures","level":"II","imp":"Distal radius fracture","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زن ۶۰ ساله با دفورمیتی مچ پس از سقوط.","why":"کاهش بسته و sugar-tong."}],"ch":"170","name":"Wrist injuries (scaphoid, carpal, lunate / perilunate dislocation, distal radius fractures)","name_fa":"آسیب‌های مچ (اسکافوئید، استخوان‌های کارپ، دررفتگی لونیت/پری‌لونیت، شکستگی‌های رادیوس دیستال)","cc":["limb-injury","joint-limb-pain","trauma-major"],"keywords":"scaphoid fracture, snuffbox tenderness, lunate dislocation, perilunate dislocation, scapholunate dissociation, Colles fracture, Smith fracture, Barton fracture, carpal fracture, sugar-tong splint, شکستگی اسکافوئید, اسنافباکس, کولس, اسمیت, بارتون","status":"draft","features":["Scapholunate dissociation: تندرنس و تورم مفصل scapholunate؛ فاصله > 3 mm در PA؛ radial gutter splint و ارجاع سریع","دررفتگی perilunate و lunate: بهتر در لترال؛ نشانه \"3 C's\" مختل؛ perilunate: lunate هم‌راستا با radius و کارپ دررفته (معمولاً دورسال)؛ lunate: lunate ولار دررفته؛ PA: \"piece of pie\"، لترال: \"spilled teacup\"؛ مشاوره اورژانس برای closed reduction یا ترمیم جراحی","اسکافوئید: شایع‌ترین شکستگی کارپ؛ خطر avascular necrosis (اسکافوئید، لونیت، کپیتیت)؛ اغلب در گرافی اولیه دیده نمی‌شود ← تشخیص و درمان بر اساس بالینی (snuffbox tenderness)؛ short-arm thumb spica","جدول 170-3: triquetrum (avulsion: short arm sugar-tong)، lunate (تندرنس مفصل دورسال دیستال به styloid اولنا)، trapezium (thumb spica)، pisiform (volar splint 30° flexion و ulnar deviation)، hamate (hook: تندرنس دیستال و رادیال pisiform؛ volar wrist splint با MC4/5 در flexion)، capitate و trapezoid (volar wrist splint / thumb spica)","Colles: زاویه دورسال، قطعه دیستال proximal و dorsal، جابه‌جایی رادیال کارپ؛ Smith: زاویه volar؛ Barton: قطعه بزرگ سطح مفصلی رادیوس به volar و proximal؛ اغلب کاهش بسته و sugar-tong splint","Radial styloid fracture: ناپایداری کارپ و scapholunate dissociation؛ اسپلینت مچ در flexion خفیف و ulnar deviation","Ulnar styloid fracture: ناپایداری مفصل radioulnar؛ ulnar gutter با مچ neutral و ulnar deviation خفیف"],"ddx":[{"n":"Perilunate / lunate dislocation |","cm":1},{"n":"Scaphoid fracture (occult) |","cm":1},{"n":"Scapholunate dissociation |"},{"n":"Distal radius fracture |"}],"redflags":["Snuffbox tenderness با گرافی نرمال، اختلال نوروواسکولار، دفورمیتی شدید"],"guide":"1) گرافی PA و لترال مچ. 2) Snuffbox tenderness ← thumb spica حتی با گرافی طبیعی. 3) دررفتگی لونیت/پری‌لونیت ← مشاوره اورژانس. 4) Colles/Smith/Barton: کاهش بسته و sugar-tong.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 170: Hand and Wrist Injuries, pp. 929–933"},"biceps-triceps-tendon-rupture":{"id":"biceps-triceps-tendon-rupture","variants":[{"id":"tendon-rupture-main","o":{"I":[{"t":"Elbow / shoulder radiographs to exclude associated avulsion fracture"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Sling immobilization; ice"}],"Co":[{"t":"Orthopedic referral in 1 week (complete tears in young active patients often need surgical repair)"}]},"name":"Biceps / triceps tendon rupture","level":"III","imp":"Biceps / triceps tendon rupture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۴۰ ساله با «pop» حین بلند کردن وزنه و توده وسط بازو.","why":"تشخیص بالینی؛ sling و ارجاع."}],"ch":"171","name":"Biceps and triceps tendon rupture","name_fa":"پارگی تاندون دوسر و سه‌سر بازو","cc":["limb-injury","joint-limb-pain"],"keywords":"biceps tendon rupture, triceps tendon rupture, biceps squeeze test, modified Thompson test, popeye deformity, پارگی تاندون بایسپس, تریسپس","status":"draft","features":["پارگی پروگزیمال سر بلند بایسپس: \"snap\" یا \"pop\" و درد شانه قدامی؛ تندرنس، تورم، کرپیتوس روی شیار بایسیپیتال؛ \"توپ\" وسط بازو با فلکسیون آرنج؛ قدرت فلکسیون حفظ (brachialis و supinators)","پارگی دیستال بایسپس: ضعف فلکسیون و سوپیناسیون آرنج؛ تورم، اکیموز، تندرنس، عدم لمس تاندون در antecubital fossa؛ biceps squeeze test (عدم سوپیناسیون = مثبت)","پارگی تریسپس: نادر، اغلب دیستال؛ درد، تورم، تندرنس پروگزیمال olecranon، sulcus با توده پروگزیمال؛ ضعف اکستنشن؛ modified Thompson test","تشخیص بالینی؛ گرافی برای رد شکستگی avulsion"],"ddx":[{"n":"Avulsion fracture |"},{"n":"Rotator cuff / shoulder pathology |"}],"redflags":["ضعف شدید فلکسیون/سوپیناسیون یا اکستنشن آرنج"],"guide":"Sling، یخ، ضددرد، ارجاع ارتوپدی (1 هفته)؛ پارگی کامل در جوان فعال اغلب ترمیم جراحی.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 171: Forearm and Elbow Injuries, pp. 934–941"},"epicondylitis":{"id":"epicondylitis","variants":[{"id":"epicondylitis-main","o":{"I":[{"t":"Radiographs only if avulsion fracture suspected"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Anti-inflammatory medication"}],"T":[{"t":"Rest, ice, forearm counterforce brace; occupational therapy"}],"Co":[{"t":"Follow-up 2–4 weeks or PRN; surgery reserved for refractory cases"}]},"name":"Epicondylitis","level":"III","imp":"Lateral / medial epicondylitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۴۵ ساله با درد جانبی آرنج پس از فعالیت تکراری.","why":"درمان محافظه‌کارانه."}],"ch":"171","name":"Lateral / medial epicondylitis (tennis elbow / golfer's elbow)","name_fa":"اپی‌کندیلیت جانبی / داخلی (آرنج تنیس‌بازان / گلف‌بازان)","cc":["joint-limb-pain","limb-injury"],"keywords":"tennis elbow, golfer elbow, lateral epicondylitis, medial epicondylitis, آرنج تنیس, اپی‌کندیلیت","status":"draft","features":["جانبی (شایع‌تر): اکستانسورهای ساعد و مچ؛ داخلی: فلکسورها؛ داخلی ممکن است با نوروپاتی اولنار همراه شود؛ ناشی از فعالیت تکراری","تشخیص بالینی؛ گرافی برای رد avulsion اپی‌کندیل"],"ddx":[{"n":"Avulsion fracture of epicondyle |"},{"n":"Ulnar neuropathy |"}],"redflags":["ندارد (خوش‌خیم)"],"guide":"درمان محافظه‌کارانه: استراحت، یخ، ضدالتهاب، بریس؛ کاردرمانی؛ جراحی فقط موارد مقاوم.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 171: Forearm and Elbow Injuries, pp. 934–941"},"elbow-dislocation":{"id":"elbow-dislocation","variants":[{"id":"elbow-dislocation-main","o":{"I":[{"t":"Elbow radiographs (AP and lateral) before and after reduction"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Procedural sedation; intra-articular lidocaine may provide analgesia"}],"T":[{"t":"Reduce (two-person traction and flexion, olecranon manipulation, or single-person hanging-arm method with 5-lb weight); range elbow fully for stability; neurovascular checks after reduction; long arm posterior splint, elbow slightly less than 90° flexion, forearm mild pronation"}],"Co":[{"t":"Orthopedic follow-up within 1 day; immediate consultation if instability, neurovascular compromise, open dislocation (admission to monitor neurovascular status); irreducible"}]},"name":"Elbow dislocation — reduction and splint","level":"II","imp":"Elbow dislocation","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مرد ۲۰ ساله پس از سقوط روی دست باز با دفورمیتی آرنج، نبض رادیال لمس می‌شود.","why":"کاهش با sedation و بررسی نوروواسکولار."}],"ch":"171","name":"Elbow dislocation","name_fa":"دررفتگی آرنج","cc":["limb-injury","trauma-major"],"keywords":"elbow dislocation, posterior elbow dislocation, brachial artery injury, reduction, long arm posterior splint, دررفتگی آرنج","status":"draft","features":["اغلب پوسترولترال پس از FOOSH؛ آرنج 45° فلکسیون؛ تورم، olecranon خلفی؛ ارزیابی نوروواسکولار اساسی (جدول 171-1)","عوامل آسیب شریانی: دررفتگی باز، نبض رادیال غایب قبل کاهش، آسیب سیستمیک","گرافی: لترال هر دو استخوان به خلف؛ AP جابه‌جایی داخلی/جانبی؛ شکستگی همراه (radial head، coronoid) ← ناپایداری","هدف: کاهش با sedation، تشخیص عوارض نوروواسکولار، شکستگی همراه و ناپایداری پس از کاهش؛ lidocaine داخل‌مفصلی","روش‌ها: دو نفره کشش و فلکسیون، دستکاری olecranon، یک نفره hanging arm با وزنه 5 lb","پس از کاهش: ROM کامل برای ثبات، معاینه نوروواسکولار، گرافی، long arm posterior splint (کمی کمتر از 90° فلکسیون، پروناسیون خفیف)، پیگیری ارتوپدی 1 روز"],"ddx":[{"n":"Supracondylar fracture |","cm":1},{"n":"Brachial artery injury |","cm":1}],"redflags":["نبض رادیال غایب، دررفتگی باز، ناپایداری"],"guide":"1) گرافی. 2) sedation یا lidocaine داخل‌مفصلی. 3) کاهش. 4) ROM و معاینه نوروواسکولار. 5) گرافی پس از کاهش. 6) اسپلینت.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 171: Forearm and Elbow Injuries, pp. 934–941"},"elbow-fractures":{"id":"elbow-fractures","variants":[{"id":"elbow-fracture-displaced","o":{"I":[{"t":"Elbow radiographs AP / lateral (fat pad signs, anterior humeral line, radiocapitellar line); CT for coronoid or comminuted intra-articular fractures"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Long arm posterior splint (presurgical stabilization); serial neurovascular assessment (Volkmann signs)"}],"Co":[{"t":"Immediate orthopedic consultation; admit displaced fractures with significant swelling for neurovascular observation"}]},"name":"Elbow fracture — displaced / open / neurovascular compromise","level":"I","imp":"Displaced elbow fracture / supracondylar fracture","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"کودک ۷ ساله پس از سقوط از تاب با دفورمیتی و تورم آرنج، نبض رادیال ضعیف.","why":"مشاوره فوری و پایش نوروواسکولار."},{"id":"elbow-fracture-nondisplaced","o":{"I":[{"t":"Elbow radiographs (fat pad sign may be only evidence)"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Nondisplaced radial head fracture without motion restriction: sling immobilization with early range of motion; other nondisplaced fractures: long arm posterior splint per Table 171-3"}],"Co":[{"t":"Orthopedic follow-up 1 week (1–2 days for some fractures)"}]},"name":"Elbow fracture — nondisplaced (radial head etc.)","level":"III","imp":"Nondisplaced elbow fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۵ ساله پس از سقوط با درد لترال آرنج و ناتوانی در اکستنشن کامل.","why":"اسپلینت و ارجاع."}],"ch":"171","name":"Elbow fractures (radial head, supracondylar, olecranon, condyle, coronoid)","name_fa":"شکستگی‌های آرنج (سر رادیوس، supracondylar، olecranon، کندیل، coronoid)","cc":["limb-injury","joint-limb-pain"],"keywords":"radial head fracture, supracondylar fracture, olecranon fracture, fat pad sign, sail sign, Essex-Lopresti, Volkmann ischemic contracture, anterior humeral line, شکستگی آرنج, supracondylar, سر رادیوس","status":"draft","features":["Radial head: درد، تورم و تندرنس لترال، ناتوانی در اکستنشن کامل؛ supracondylar/intercondylar: تورم و محدودیت ROM (ممکن است شبیه دررفتگی خلفی)؛ olecranon: درد، تورم، کرپیتوس خلفی","Essex–Lopresti: شکستگی سر رادیوس + dissociation مفصل رادیواولنار دیستال (درد مچ و ساعد)","ارزیابی نوروواسکولار در همه؛ نبض رادیال کاهش‌یافته/غایب در کودکان شایع (آسیب شریان brachial) حتی با دست گرم؛ علائم Volkmann (امتناع از باز کردن دست، درد با اکستنشن پاسیو انگشتان، تندرنس ساعد)؛ نبض غایب به تنهایی ایسکمی نیست","عوارض supracondylar (جدول 171-2): عصب رادیال، median (anterior interosseous)، اولنار، Volkmann، nonunion، malunion، myositis ossificans","گرافی: fat pad غیرطبیعی (posterior fat pad، sail sign)؛ radiocapitellar line؛ anterior humeral line (خط از کورتکس قدامی هومروس باید 2/3 خلفی capitellum را قطع کند)؛ CT برای coronoid یا comminuted intra-articular","اسپلینت و ارجاع در بدون جابه‌جایی؛ radial head بدون جابه‌جایی و بدون محدودیت: sling؛ مشاوره فوری ارتوپدی برای جابه‌جایی، باز، اختلال نوروواسکولار؛ بستری در جابه‌جایی با تورم زیاد"],"ddx":[{"n":"Brachial artery injury / compartment syndrome |","cm":1},{"n":"Elbow dislocation |","cm":1},{"n":"Occult fracture (fat pad sign) |"}],"redflags":["نبض غایب، علائم Volkmann، شکستگی باز، جابه‌جایی"],"guide":"جدول 171-3: supracondylar: long arm posterior splint (stabilization before surgery) - immediate؛ intercondylar: neutral، 1–2 days؛ lateral condyle nondisplaced: supination، wrist extended؛ medial nondisplaced: pronation، wrist flexed؛ coronoid/olecranon: long arm posterior splint؛ radial head nondisplaced: sling با early ROM، 1 week.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 171: Forearm and Elbow Injuries, pp. 934–941"},"forearm-fractures":{"id":"forearm-fractures","variants":[{"id":"forearm-fracture-main","o":{"I":[{"t":"AP and lateral forearm radiographs including elbow and wrist (radiocapitellar line; DRUJ)"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Long arm splint immobilization (presurgical stabilization for displaced fractures, Monteggia, Galeazzi); neurovascular checks"}],"Co":[{"t":"Immediate orthopedic consultation for displaced fractures (ORIF usually required in adults, Monteggia, Galeazzi); nondisplaced / torus / greenstick < 15°: long arm splint and orthopedic referral"}]},"name":"Forearm fracture — displaced / Monteggia / Galeazzi","level":"II","imp":"Forearm fracture","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله پس از سقوط با دفورمیتی ساعد.","why":"گرافی و مشاوره ارتوپدی."}],"ch":"171","name":"Forearm fractures (both-bone, Monteggia, Galeazzi)","name_fa":"شکستگی‌های ساعد (هر دو استخوان، Monteggia، Galeazzi)","cc":["limb-injury","trauma-major"],"keywords":"forearm fracture, both bone fracture, Monteggia, Galeazzi, radial head dislocation, ulna shaft fracture, greenstick, شکستگی ساعد, مونتژیا, گالیازی","status":"draft","features":["هر دو استخوان: تورم، تندرنس، دفورمیتی؛ ایزوله رادیوس/اولنا: تورم و تندرنس موضعی","Monteggia: شکستگی ثلث پروگزیمال اولنا + دررفتگی سر رادیوس؛ radiocapitellar line مختل و رأس شکستگی به سمت دررفتگی","Galeazzi: شکستگی رادیوس دیستال + دررفتگی DRUJ؛ فضای DRUJ پهن در AP و اولنا دورسال در لترال","AP و لترال تشخیص می‌دهد؛ بدون جابه‌جایی، torus یا greenstick < 15° angulation: long arm splint و ارجاع؛ مشاوره فوری برای همه جابه‌جایی‌ها؛ کودکان closed reduction اغلب کافی؛ بزرگسال جابه‌جایی‌دار، Monteggia و Galeazzi: ORIF"],"ddx":[{"n":"Compartment syndrome |","cm":1},{"n":"Open fracture |","cm":1},{"n":"Elbow / wrist injury |"}],"redflags":["درد خارج از تناسب، کمپارتمان، شکستگی باز"],"guide":"اسپلینت (جدول 171-3): both bones بدون جابه‌جایی: long arm splint، 1 week؛ جابه‌جایی‌دار: presurgical stabilization، immediate؛ Monteggia/Galeazzi: immediate.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 171: Forearm and Elbow Injuries, pp. 934–941"},"sternoclavicular-injury":{"id":"sternoclavicular-injury","variants":[{"id":"sc-injury-main","o":{"I":[{"t":"CT chest (contrast if mediastinal injury suspected); CXR"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Ice; sling immobilization (sprain / uncomplicated anterior dislocation; closed reduction not necessary)"}],"Co":[{"t":"Immediate orthopedic consultation for posterior dislocation (open reduction and internal fixation)"}]},"name":"Sternoclavicular sprain / dislocation","level":"II","imp":"Sternoclavicular injury","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مرد ۲۸ ساله پس از برخورد در ورزش با درد جلوی قفسه و کلاویکل برجسته.","why":"CT؛ خلفی ← مشاوره فوری."}],"ch":"172","name":"Sternoclavicular sprain and dislocation","name_fa":"رگ‌به‌رگ‌شدگی و دررفتگی استرنوکلاویکولار","cc":["limb-injury","chest-pain","trauma-major"],"keywords":"sternoclavicular dislocation, posterior SC dislocation, mediastinal injury, استرنوکلاویکولار","status":"draft","features":["سرکوفتگی ساده: درد و تندرنس موضعی؛ دررفتگی: درد شدید بدتر با حرکت بازو و خوابیدن به پشت؛ قدامی: انتهای medial کلاویکل برجسته؛ خلفی: کمتر مشهود","خلفی با خشونت صدا، دیسفاژی، تنگی نفس، پارستزی/ضعف اندام فوقانی ← آسیب مدیاستن (پنوموتوراکس، عروق بزرگ، تراشه، مری)","CT انتخاب اول؛ کنتراست برای آسیب مدیاستن؛ در غیر تروما: آرتریت سپتیک (به‌ویژه تزریق مواد)"],"ddx":[{"n":"Mediastinal injury (posterior) |","cm":1},{"n":"Septic arthritis (nontraumatic) |"}],"redflags":["دیسپنه، دیسفاژی، خشونت صدا، پارستزی"],"guide":"قدامی بدون عارضه: یخ، ضددرد، sling؛ کاهش بسته لازم نیست؛ خلفی: مشاوره فوری ارتوپدی (ORIF).","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 172: Shoulder and Humerus Injuries, pp. 942–948"},"clavicle-scapula-fracture":{"id":"clavicle-scapula-fracture","variants":[{"id":"clavicle-scapula-main","o":{"I":[{"t":"Shoulder / clavicle radiographs; CXR; CT if scapular fracture or radiographs equivocal (and for associated pathology)"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Sling immobilization, ice, early range-of-motion exercises"}],"Co":[{"t":"Orthopedic consultation: open fracture, neurovascular compromise, persistent skin tenting; severely comminuted or displaced clavicle; displaced glenoid articular / angulated glenoid neck fractures"}]},"name":"Clavicle / scapula fracture","level":"III","imp":"Clavicle / scapula fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"PA","sc":"مرد ۲۵ ساله پس از سقوط از دوچرخه با درد و تورم ترقوه.","why":"sling؛ اسکاپولا ← بررسی آسیب توراکس."}],"ch":"172","name":"Clavicle and scapula fractures","name_fa":"شکستگی کلاویکل و اسکاپولا","cc":["limb-injury","trauma-major"],"keywords":"clavicle fracture, scapula fracture, skin tenting, glenoid fracture, شکستگی ترقوه, اسکاپولا","status":"draft","features":["کلاویکل: درد، تورم، تندرنس؛ اسکاپولا: استخوان محافظت‌شده؛ شکستگی اغلب همراه آسیب ریه، توراکس و کمربند شانه؛ بازو در adduction","گرافی ممکن است برخی را از دست بدهد؛ CT تأیید و آسیب‌های همراه","مدیریت محافظه‌کارانه با sling، یخ، ضددرد و early ROM؛ مشاوره ارتوپدی برای باز، اختلال نوروواسکولار، skin tenting دائمی؛ comminuted شدید یا جابه‌جایی ← ارجاع زودرس","شکستگی اسکاپولا: بررسی آسیب داخل‌توراکس؛ glenoid articular جابه‌جایی‌دار، glenoid neck زاویه‌دار، بعضی acromion و coracoid ممکن جراحی"],"ddx":[{"n":"Pneumothorax / hemothorax / intrathoracic injury |","cm":1},{"n":"Neurovascular injury |","cm":1}],"redflags":["skin tenting، اختلال نوروواسکولار، شکستگی باز، شکستگی اسکاپولا (آسیب توراکس)"],"guide":"Sling، یخ، ضددرد، early ROM؛ اسکاپولا ← CXR/CT و جستجوی آسیب توراکس.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 172: Shoulder and Humerus Injuries, pp. 942–948"},"ac-joint-injury":{"id":"ac-joint-injury","variants":[{"id":"ac-joint-main","o":{"I":[{"t":"AC joint radiographs (axillary view if type IV suspected)"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Sling immobilization, rest, ice; early range-of-motion at 7–14 days (types I–II; type III generally conservative)"}],"Co":[{"t":"Orthopedic consultation for types IV–VI (operative)"}]},"name":"AC joint injury","level":"III","imp":"Acromioclavicular joint injury","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله پس از سقوط روی شانه با برجستگی انتهای کلاویکل.","why":"نوع بندی و sling؛ IV–VI ← جراحی."}],"ch":"172","name":"Acromioclavicular joint injury (Rockwood types I–VI)","name_fa":"آسیب مفصل آکرومیوکلاویکولار (انواع I تا VI)","cc":["limb-injury","joint-limb-pain"],"keywords":"acromioclavicular separation, AC joint, shoulder separation, clavicle elevated, آکرومیوکلاویکولار, جداشدگی شانه","status":"draft","features":["از رگ‌به‌رگ‌شدگی خفیف تا گسیختگی کامل؛ مکانیسم: ضربه مستقیم با بازو adducted یا FOOSH","نوع I: گرافی طبیعی، تندرنس؛ II: AC ligament پاره، CC رگ‌به‌رگ، کلاویکل 25%–50% بالاتر، step-off خفیف؛ III: هر دو پاره، کلاویکل 100% بالاتر، CC interspace 25%–100% پهن، شانه افتاده؛ IV: کلاویکل خلفی (axillary view لازم)؛ V: 200%–300% اختلاف CC؛ VI: کلاویکل به سمت پایین، آسیب‌های همراه","تشخیص بالینی؛ گرافی AC برای شدت و شکستگی همراه"],"ddx":[{"n":"Clavicle fracture |"},{"n":"Glenohumeral dislocation |"}],"redflags":["نوع IV تا VI، آسیب‌های همراه"],"guide":"نوع I و II: sling، استراحت، یخ، ضددرد، ROM زودرس در 7–14 روز؛ III بحث‌برانگیز (روند: محافظه‌کارانه با sling)؛ IV–VI: جراحی و مشاوره ارتوپدی.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 172: Shoulder and Humerus Injuries, pp. 942–948"},"shoulder-dislocation":{"id":"shoulder-dislocation","variants":[{"id":"shoulder-dislocation-main","o":{"I":[{"t":"Shoulder radiographs: AP and scapular Y (may omit pre-reduction films in recurrent dislocation with no trauma); post-reduction radiographs"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Procedural sedation; alternatively intra-articular injection of 10–20 mL of 1% lidocaine"}],"T":[{"t":"Reduce (traction-countertraction: modified Hippocratic, Snowbird; Stimson with 10-lb weight; scapular manipulation; external rotation / Kocher; Milch; Cunningham); assess neurovascular status; sling to hold shoulder in adduction and internal rotation"}],"Co":[{"t":"Urgent orthopedic follow-up (early operative repair may decrease recurrence)"}]},"name":"Shoulder dislocation — reduction","level":"II","imp":"Glenohumeral dislocation","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مرد ۲۲ ساله پس از ضربه در ورزش با دفورمیتی شانه، بازو در ابداکشن و چرخش خارجی.","why":"گرافی، کاهش، sling."}],"ch":"172","name":"Glenohumeral (shoulder) dislocation","name_fa":"دررفتگی شانه (گلنوهومرال)","cc":["limb-injury","joint-limb-pain"],"keywords":"shoulder dislocation, anterior dislocation, posterior dislocation, luxatio erecta, axillary nerve, Hill-Sachs, Bankart, reduction techniques, دررفتگی شانه","status":"draft","features":["قدامی (شایع‌ترین): نیروی abduction، extension، external rotation؛ بازو در abduction و چرخش خارجی خفیف؛ کانتور شانه از بین رفته؛ کاهش حس لترال دلتوئید ← آسیب عصب axillary","خلفی: نیروی غیرمستقیم یا ضربه مستقیم؛ تخت‌شدن قدام شانه، برجستگی خلفی؛ ناتوان در چرخش خارجی و ابداکشن","تحتانی (luxatio erecta): hyperabduction؛ بازو کاملاً ابداکت، آرنج فلکس، دست روی سر؛ superior بسیار نادر","AP و scapular Y؛ Hill–Sachs و Bankart مدیریت را تغییر نمی‌دهند؛ در عود بدون تروما می‌توان گرافی قبل کاهش را حذف کرد","تکنیک‌ها: modified Hippocratic، Snowbird، Stimson (وزنه 10 lb، 20–30 دقیقه)، scapular manipulation، Kocher external rotation، Milch، Cunningham؛ sedation یا lidocaine 1% داخل‌مفصلی 10–20 mL","پس از کاهش: معاینه نوروواسکولار، sling (adduction و internal rotation)، گرافی تأیید؛ پیگیری فوری ارتوپدی؛ عوارض: عود، rotator cuff، defect سر هومروس، labral، نوروواسکولار"],"ddx":[{"n":"Proximal humerus fracture |","cm":1},{"n":"Rotator cuff tear |"},{"n":"AC injury |"}],"redflags":["اختلال نوروواسکولار، شکستگی همراه"],"guide":"1) گرافی AP + Y. 2) sedation یا lidocaine داخل‌مفصلی. 3) یکی از تکنیک‌های کاهش (حداقل 2–3 تکنیک). 4) معاینه نوروواسکولار. 5) sling. 6) گرافی بعد کاهش.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 172: Shoulder and Humerus Injuries, pp. 942–948"},"humerus-fracture":{"id":"humerus-fracture","variants":[{"id":"humerus-fracture-main","o":{"I":[{"t":"Shoulder / humerus radiographs (Neer classification)"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Nondisplaced / one-part proximal: sling, ice; nondisplaced shaft: coaptation (sugar-tong) splint, hanging cast or functional brace; careful neurovascular exam (radial nerve in shaft, axillary in proximal)"}],"Co":[{"t":"Immediate orthopedic consultation: multipart proximal, significantly displaced or angulated shaft, open fracture, neurovascular injury; otherwise orthopedic referral"}]},"name":"Humerus fracture","level":"II","imp":"Humerus fracture (proximal / shaft)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زن ۷۰ ساله پس از سقوط با درد و کبودی شانه و محدودیت حرکت.","why":"گرافی و تعیین جراحی/محافظه‌کارانه."}],"ch":"172","name":"Humerus fractures (proximal and shaft)","name_fa":"شکستگی هومروس (پروگزیمال و شفت)","cc":["limb-injury","trauma-major"],"keywords":"proximal humerus fracture, humeral shaft fracture, Neer classification, radial nerve injury, wrist drop, coaptation splint, شکستگی هومروس, عصب رادیال","status":"draft","features":["پروگزیمال: درد، تورم، تندرنس، اکیموز، کرپیتوس؛ ROM شدیداً محدود؛ شفت: درد، تورم، تندرنس، کرپیتوس؛ کوتاه‌شدگی در جابه‌جایی‌دار","آسیب عصب و شریان axillary در پروگزیمال؛ عصب رادیال در شفت (ضعف اکستنشن مچ، wrist drop، تغییر حس web space)","Neer: چهار قسمت (سطح مفصلی، greater tubercle، lesser tubercle، دیافیز)","پروگزیمال بدون جابه‌جایی یا one-part (< 1 cm جابه‌جایی، < 45° زاویه): sling، یخ، ضددرد، ارجاع؛ شفت بدون جابه‌جایی: coaptation splint (sugar tong)، hanging cast یا functional bracing؛ محافظه‌کارانه اگر < 20° sagittal، < 30° varus/valgus، < 2 cm کوتاهی","مشاوره فوری: multipart، جابه‌جایی/زاویه‌دار قابل‌توجه، باز، آسیب نوروواسکولار"],"ddx":[{"n":"Neurovascular injury (radial / axillary) |","cm":1},{"n":"Shoulder dislocation |"}],"redflags":["wrist drop، نبض مختل، شکستگی باز"],"guide":"گرافی؛ معاینه دقیق نوروواسکولار؛ sling یا coaptation splint؛ مشاوره فوری در شرایط بالا.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 172: Shoulder and Humerus Injuries, pp. 942–948"},"brachial-plexus-injury":{"id":"brachial-plexus-injury","variants":[{"id":"brachial-plexus-main","o":{"I":[{"t":"Cervical spine / shoulder imaging; MRI or CT myelography as directed; EMG / nerve conduction studies (follow-up)"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Stabilize; evaluate associated neck / shoulder girdle injuries; neurologic documentation"}],"Co":[{"t":"Neurosurgery / orthopedic (nerve) referral"}]},"name":"Brachial plexus injury","level":"II","imp":"Brachial plexus injury","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"PA","sc":"مرد ۲۵ ساله پس از تصادف موتور با درد سوزشی بازو و ضعف.","why":"شناسایی و ارجاع."}],"ch":"172","name":"Brachial plexus injury (traumatic)","name_fa":"آسیب شبکه براکیال (تروماتیک)","cc":["limb-injury","weakness","focal-neuro"],"keywords":"brachial plexus injury, Horner syndrome, supraclavicular, infraclavicular, nerve injury arm, شبکه براکیال","status":"draft","features":["شایع‌ترین شکل آسیب پلکسوس؛ نافذ، فشاری یا کشش بسته؛ سوپراکلاویکولار (ریشه‌ها و تنه‌ها) یا اینفراکلاویکولار (کردها و اعصاب انتهایی)","درد مداوم سوزشی بازو و کمبود حسی/حرکتی؛ تورم و آسیب نسج نرم گردن/شانه؛ Horner در آسیب گانگلیون مجاور؛ در بیمار غیرهوشیار تا پایان احیا مشخص نمی‌شود","تشخیص عمدتاً بالینی؛ MRI و CT myelography، EMG/NCV؛ گاهی اکتشاف جراحی","محل و وسعت آسیب درمان و پیش‌آگهی را تعیین می‌کند"],"ddx":[{"n":"Cervical spine / spinal cord injury |","cm":1},{"n":"Vascular injury |","cm":1},{"n":"Peripheral nerve injury |"}],"redflags":["Horner، ضعف پیشرونده، آسیب عروقی همراه"],"guide":"شناسایی و ارجاع مناسب.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 172: Shoulder and Humerus Injuries, pp. 942–948"},"pelvic-fracture":{"id":"pelvic-fracture","variants":[{"id":"pelvic-fracture-unstable","o":{"I":[{"t":"AP pelvis radiograph; CXR portable; FAST (thorax and peritoneal cavity); CT when stable or responds to resuscitation"}],"L":[{"t":"Type and crossmatch, CBC, coagulation studies, lactate, urinalysis"}],"S":[{"t":"IV crystalloid and blood products","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Pelvic binding device or bedsheet; avoid excessive movement; rectal and (if indicated) vaginal speculum exam; evaluate for urethral injury before catheter (blood at meatus)"}],"Co":[{"t":"Emergent trauma surgery / orthopedics; angiography with embolization and external fixation (if unavailable or delayed: extraperitoneal packing); laparotomy if FAST positive"}]},"name":"Pelvic fracture — unstable / hemodynamically unstable","level":"I","imp":"Pelvic fracture with hemorrhagic shock","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen","sc":"مرد ۴۰ ساله پس از تصادف با فشار 75/40، لگن ناپایدار و خون در میتوس.","why":"binder، احیا، یافتن منبع خونریزی."},{"id":"pelvic-fracture-stable","o":{"I":[{"t":"AP pelvis radiograph (CT if high suspicion with negative films); Judet views / CT for acetabulum"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesics"}],"T":[{"t":"Crutches; bed rest 3–4 weeks with hip flexed for avulsion fractures; stool softeners, sitz bath, donut-ring cushion (coccyx / ischium); nonweight-bearing for iliac wing until abductors pain-free"}],"Co":[{"t":"Orthopedic follow-up 1–2 weeks (admit for open fracture or concerning abdominal exam; consult for displaced sacral fractures or neurologic deficit); acetabular fractures: orthopedic consultation and admission"}]},"name":"Pelvic fracture — stable (single bone / avulsion / nondisplaced)","level":"III","imp":"Stable pelvic fracture (single bone / avulsion)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۱۶ ساله فوتبالیست با درد مفصل ران و فلکسیون پس از شوت (avulsion AIIS).","why":"ضددرد و استراحت."}],"ch":"173","name":"Pelvic fracture (ring, acetabular, single bone / avulsion)","name_fa":"شکستگی لگن (حلقه لگن، استابولوم، تک‌استخوانی / avulsion)","cc":["trauma-major","hypotension-shock","joint-limb-pain"],"keywords":"pelvic fracture, pelvic binder, unstable pelvis, acetabular fracture, Judet views, angiography embolization, iliac wing fracture, sacral fracture, coccyx fracture, شکستگی لگن, بایندر لگن, استابولوم","status":"draft","features":["علائم از درد موضعی تا ناپایداری و شوک شدید؛ درد، ناپایداری لگن، دفورمیتی، لاسراسیون، اکیموز، هماتوم؛ از حرکت اضافی ناپایدار پرهیز (خونریزی بیشتر)","RE: جابه‌جایی پروستات یا آسیب رکتوم؛ خون در میتوس ← آسیب پیشابراه؛ معاینه اسپکولوم واژن برای لاسراسیون (شکستگی باز)؛ فرض آسیب‌های همراه داخل‌شکمی، رتروپریتوان، زنان یا ادراری تا اثبات خلاف","AP لگن؛ سایر نماها: لترال، hemipelvis، oblique، inlet / outlet؛ CT بهتر از گرافی؛ در تروما ناپایدار AP لگن سریع؛ در پایدار که CT شکم-لگن می‌شود نیاز به گرافی روتین نیست","استابولوم: فشار لترال یا دررفتگی هیپ؛ گرافی + Judet؛ CT حساس‌تر","شکستگی تک‌استخوانی (جدول 173-1): iliac wing، ramus پوبیس/ایسکیوم، ایسکیوم، ساکروم، coccyx، avulsion ASIS/AIIS/ischial tuberosity ← ضددرد، استراحت، crutches؛ ترخیص با پیگیری 1–2 هفته؛ بستری در باز یا معاینه شکمی نگران‌کننده","با استثنای lateral compression type I و AP compression type I، سایر شکستگی‌های حلقه نیاز به ORIF؛ استابولوم: مشاوره و بستری"],"ddx":[{"n":"Intra-abdominal / retroperitoneal hemorrhage |","cm":1},{"n":"Urethral / bladder / rectal injury |","cm":1},{"n":"Hip dislocation / acetabular fracture |","cm":1}],"redflags":["ناپایداری همودینامیک، لگن ناپایدار، خون میتوس، شکستگی باز"],"guide":"الگوریتم شکل 173-1: ناپایدار با binder ← FAST: منفی ← آنژیوگرافی/embolization؛ مثبت ← لاپاراتومی؛ پایدار ← CT. 1) احیا با کریستالوئید و خون. 2) binder یا ملحفه. 3) CXR و FAST برای منابع خونریزی دیگر. 4) آنژیوگرافی با embolization و external fixation.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 173: Pelvis, Hip, and Femur Injuries, pp. 949–955"},"hip-fracture":{"id":"hip-fracture","variants":[{"id":"hip-fracture-main","o":{"I":[{"t":"AP and lateral hip radiographs; AP pelvis (comparison); femur / knee radiographs if indicated; CXR"}],"L":[{"t":"CBC, BUN, Cr, Na, K; coagulation studies, type and screen (preoperative testing and clearance)"}],"S":[{"t":"IV analgesia"}],"T":[{"t":"No traction in femoral neck fracture (traction contraindicated); NPO (anticipated surgery); neurovascular checks"}],"Co":[{"t":"Orthopedic service admission (femoral neck, intertrochanteric, subtrochanteric: ORIF / arthroplasty); orthopedic consultation immediately for femoral head fracture / dislocation"}]},"name":"Hip fracture (elderly after fall)","level":"II","imp":"Hip fracture","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"زن ۸۰ ساله پس از سقوط با پای کوتاه و چرخش خارجی.","why":"گرافی، آنالژزی، بستری ارتوپدی."},{"id":"hip-fracture-occult","o":{"I":[{"t":"MRI hip in ED (nearly 100% sensitive), or arrange MRI within 24–48 hours; CT if MRI unavailable (less sensitive)"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Non-weight-bearing until MRI"}],"Co":[{"t":"Orthopedic follow-up / consultation based on MRI"}]},"name":"Suspected occult hip fracture (normal radiographs, cannot bear weight)","level":"III","imp":"Suspected occult hip fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۷۰ ساله پس از سقوط با درد شدید کشاله ران و ناتوان در تحمل وزن، گرافی طبیعی.","why":"MRI تشخیص می‌دهد."}],"ch":"173","name":"Hip fracture (femoral head, neck, trochanteric, intertrochanteric, subtrochanteric) / occult hip fracture","name_fa":"شکستگی هیپ (سر، گردن، تروکانتریک، اینترتروکانتریک، ساب‌تروکانتریک) / شکستگی مخفی هیپ","cc":["limb-injury","joint-limb-pain"],"keywords":"hip fracture, femoral neck fracture, intertrochanteric, subtrochanteric, occult hip fracture, MRI hip, elderly fall, شکستگی هیپ, گردن فمور, MRI","status":"draft","features":["اکثراً سالمند با استئوپروز پس از سقوط؛ پا کوتاه و چرخش خارجی؛ درد محل، کشاله ران یا زانو","معاینه: درد، کوتاه‌شدگی، چرخش، دفورمیتی، تندرنس لگن/ساکروم، وضعیت نوروواسکولار؛ سقوط یا تروما ← سایر آسیب‌ها","جدول 173-2: سر فمور (ایزوله نادر؛ 6–16% دررفتگی هیپ)؛ گردن (شایع سالمند)؛ greater trochanter (ambulatory، درد با ابداکشن)؛ lesser (avulsion)؛ intertrochanteric (شایع سالمند)؛ subtrochanteric (15%؛ ممکن پاتولوژیک)","گرافی AP و لترال هیپ، AP لگن، Judet؛ درد با تحمل وزن و گرافی طبیعی ← شک مخفی (گردن فمور یا استابولوم)؛ MRI حساسیت تقریباً 100%؛ CT کمتر حساس","جدول 173-3: سر فمور: مشاوره فوری، کاهش اورژانس؛ گردن: مشاوره، nonoperative تا total hip arthroplasty؛ greater trochanter: ضددرد و protected weight-bearing؛ lesser: ضددرد (بررسی پاتولوژیک)؛ intertrochanteric/subtrochanteric: بستری برای ORIF؛ subtrochanteric: Hare/Sager splint","شک بالا به occult: MRI در ED یا MRI طی 24–48 ساعت با non-weight-bearing؛ traction در گردن فمور کنتراندیکه"],"ddx":[{"n":"Pelvic fracture / acetabular fracture |","cm":1},{"n":"Hip dislocation |","cm":1},{"n":"Femoral shaft fracture |"},{"n":"Sprain / strain |"},{"n":"Pathologic fracture |"}],"redflags":["پای کوتاه و چرخش خارجی، ناتوان در تحمل وزن، گرافی طبیعی با درد شدید"],"guide":"جدول 173-3 را برای هر نوع ببینید؛ بستری ارتوپدی برای اکثر موارد؛ MRI برای شک مخفی.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 173: Pelvis, Hip, and Femur Injuries, pp. 949–955"},"hip-dislocation":{"id":"hip-dislocation","variants":[{"id":"hip-dislocation-main","o":{"I":[{"t":"AP pelvis and hip radiographs; Judet views or CT for acetabulum / femur; post-reduction radiographs or CT; CXR portable (trauma)"}],"L":[{"t":"Type and screen, CBC"}],"S":[{"t":"Procedural sedation; analgesia"}],"T":[{"t":"Allis maneuver (posterior dislocation): pelvis stabilized, upward pull on femur with internal and external rotation; gently test ROM after reduction; neurovascular examination before and after"}],"Co":[{"t":"Orthopedic consultation immediately (prosthetic hips: discuss plan before reduction); post-reduction care coordinated with orthopedist"}]},"name":"Hip dislocation — emergent reduction within 6 hours","level":"I","imp":"Hip dislocation","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مرد ۳۰ ساله پس از تصادف با پای کوتاه، چرخش داخلی و adduction.","why":"کاهش < 6 ساعت برای کاهش AVN."}],"ch":"173","name":"Hip dislocation (native and prosthetic)","name_fa":"دررفتگی هیپ (طبیعی و پروتزی)","cc":["trauma-major","limb-injury","joint-limb-pain"],"keywords":"hip dislocation, posterior hip dislocation, Allis maneuver, avascular necrosis, prosthetic hip dislocation, دررفتگی هیپ, مانور آلیس","status":"draft","features":["قدامی یا خلفی؛ اغلب تصادف سرعت بالا؛ 90% خلفی (ممکن شکستگی استابولوم)","خلفی: کوتاه، چرخش داخلی، adduction؛ قدامی: abduction و چرخش خارجی؛ ارزیابی نوروواسکولار (عصب سیاتیک)","گرافی هیپ و لگن؛ Judet یا CT","اورژانس واقعی ارتوپدی: کاهش در < 6 ساعت (تأخیر ← AVN)؛ مانور Allis (شکل 173-2)؛ ROM خفیف، معاینه نوروواسکولار، گرافی/CT پس از کاهش","هیپ پروتزی: با فلکسیون > 90° یا آسیب جزئی دررفته؛ خلفی؛ قبل از کاهش با ارتوپد مشورت"],"ddx":[{"n":"Femoral head / acetabular fracture |","cm":1},{"n":"Sciatic nerve injury |","cm":1},{"n":"Femoral neck fracture |"}],"redflags":["تأخیر کاهش > 6 ساعت، آسیب نوروواسکولار"],"guide":"گرافی → sedation → Allis → معاینه نوروواسکولار → گرافی/CT پس از کاهش.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 173: Pelvis, Hip, and Femur Injuries, pp. 949–955"},"femoral-shaft-fracture":{"id":"femoral-shaft-fracture","variants":[{"id":"femoral-shaft-main","o":{"I":[{"t":"Femur radiographs (including hip and knee); CXR portable; trauma imaging as indicated"}],"L":[{"t":"Type and crossmatch, coagulation studies, lactate"}],"S":[{"t":"IV crystalloid / blood as needed ; IV analgesia","fl":[{"k":"hi","v":""}]}],"A":[{"t":"Open fracture: broad-spectrum antibiotics with copious irrigation"}],"T":[{"t":"Traction splint unless sciatic nerve, knee, or vascular injury or open fracture (then splint without traction); neurovascular status; NPO"}],"Co":[{"t":"Early orthopedic consultation for definitive management"}]},"name":"Femoral shaft fracture","level":"I","imp":"Femoral shaft fracture","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مرد ۲۵ ساله پس از تصادف موتور با ران متورم و کوتاه.","why":"اسپلینت کششی، کنترل خونریزی، ارتوپدی."}],"ch":"173","name":"Femoral shaft fracture","name_fa":"شکستگی شفت فمور","cc":["limb-injury","trauma-major"],"keywords":"femoral shaft fracture, traction splint, open femur fracture, pathologic fracture, شکستگی شفت فمور, اسپلینت کششی","status":"draft","features":["بیشتر در جوانان با تروما پرانرژی؛ پاتولوژیک در بدخیمی؛ کوتاه‌شدگی، درد، تورم، دفورمیتی","وضعیت نوروواسکولار، علائم باز، آسیب‌های همراه","اسپلینت کششی (traction splint) مگر: آسیب سیاتیک، زانو، عروقی یا شکستگی باز ← بدون کشش","شکستگی باز: آنتی‌بیوتیک وسیع‌الطیف و شستشوی فراوان؛ مشاوره زودهنگام ارتوپدی"],"ddx":[{"n":"Hemorrhagic shock (thigh blood loss) |","cm":1},{"n":"Open fracture / vascular injury |","cm":1},{"n":"Pathologic fracture |"}],"redflags":["ناپایداری، شکستگی باز، نبض مختل"],"guide":"Traction splint؛ آنتی‌بیوتیک و شستشو در باز؛ مشاوره ارتوپدی.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 173: Pelvis, Hip, and Femur Injuries, pp. 949–955"},"knee-leg-fractures":{"id":"knee-leg-fractures","variants":[{"id":"knee-leg-fracture-main","o":{"I":[{"t":"Knee radiographs per Ottawa / Pittsburgh rules; ankle and knee radiographs for tibia / fibula injuries; CT if negative radiographs and unable to bear weight"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"A":[{"t":"Open fracture: irrigation and antistaphylococcal antibiotics in the ED"}],"T":[{"t":"Knee immobilizer or long-leg immobilization; ice, elevation; thorough neurovascular exam (high compartment syndrome risk with tibial fractures)"}],"Co":[{"t":"Emergent orthopedic consultation (open fracture, vascular compromise, compartment syndrome → emergent surgery); most tibial fractures require emergent consult; low-energy, pain controlled, no compartment risk: long-leg immobilization and discharge; isolated fibular shaft: splint, ice, elevation, follow-up"}]},"name":"Knee / leg fracture","level":"II","imp":"Knee / leg fracture","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مرد ۴۵ ساله پس از سقوط با تورم و درد زانو و ناتوانی در راه رفتن.","why":"گرافی و مشاوره ارتوپدی."}],"ch":"174","name":"Knee and leg fractures (patella, femoral condyle, tibial plateau, tibial shaft, fibula)","name_fa":"شکستگی‌های زانو و ساق (کشکک، کندیل فمور، plateau تیبیا، شفت تیبیا، فیبولا)","cc":["limb-injury","joint-limb-pain"],"keywords":"patella fracture, tibial plateau fracture, tibial shaft fracture, Pilon fracture, Ottawa knee rules, Pittsburgh knee rules, compartment syndrome, شکستگی کشکک, تیبیا, قوانین اتاوا","status":"draft","features":["کشکک: تندرنس موضعی، تورم، فقدان مکانیسم extensor؛ کندیل فمور: درد، تورم، دفورمیتی، چرخش، کوتاهی، ناتوان در راه رفتن (آسیب پوپلیتئال، deep peroneal، هیپ، quadriceps)؛ tibial spine: تندرنس، تورم، ناتوان در extension، Lachman مثبت؛ plateau: درد، تورم، ROM محدود، ناپایداری لیگامانی ~ 1/3؛ شفت تیبیا: درد، تورم، کرپیتوس؛ Pilon: درد و تورم مچ؛ فیبولا: ممکن راه رفتن؛ proximal fibula مرتبط با آسیب مچ","خطر بالای کمپارتمان در شکستگی تیبیا ← معاینه نوروواسکولار دقیق","قوانین رادیوگرافی: Pittsburgh (شکل 174-1) یا Ottawa (جدول 174-1: سن > 55، تندرنس head فیبولا، تندرنس ایزوله کشکک، ناتوان در فلکسیون 90°، ناتوان در 4 قدم)","CT اگر گرافی منفی و ناتوان در تحمل وزن","مشاوره فوری ارتوپدی برای اکثر تیبیا؛ جراحی اورژانس: باز، آسیب عروقی، کمپارتمان؛ long-leg immobilization و ترخیص در مکانیسم کم‌انرژی، درد کنترل‌شده، بدون خطر کمپارتمان","جدول 174-2: کشکک بدون جابه‌جایی با extensor سالم: knee immobilizer، استراحت، یخ، ضددرد؛ جابه‌جایی > 3 mm یا ناهمواری > 2 mm یا اختلال extensor: ارجاع زودرس ORIF؛ باز: شستشو و آنتی‌بیوتیک ضداستافیلوکوک؛ کندیل: ناقص/بدون جابه‌جایی: اسپلینت و ارجاع؛ جابه‌جایی‌دار: ORIF؛ plateau بدون جابه‌جایی: knee immobilizer، non-weight-bearing و ارجاع 2–7 روز؛ depression: ORIF"],"ddx":[{"n":"Compartment syndrome |","cm":1},{"n":"Open fracture / vascular injury |","cm":1},{"n":"Knee dislocation (spontaneously reduced) |"},{"n":"Ligamentous injury |"}],"redflags":["نبض مختل، درد خارج از تناسب، شکستگی باز، پوست باز"],"guide":"قوانین Ottawa/Pittsburgh برای نیاز گرافی؛ تیبیا: مشاوره فوری؛ ایزوله فیبولا: اسپلینت، یخ، elevation و پیگیری.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 174: Knee and Leg Injuries, pp. 956–960"},"knee-dislocation":{"id":"knee-dislocation","variants":[{"id":"knee-dislocation-main","o":{"I":[{"t":"Knee radiographs (exclude fractures); ankle-brachial index with serial vascular exams (or arteriography / CT angiography per consultant)"}],"L":[{"t":"Type and screen, CBC"}],"S":[{"t":"Procedural sedation; analgesia"}],"T":[{"t":"Early reduction with documentation of pre- and post-reduction neurovascular status; splint in 20° flexion"}],"Co":[{"t":"Immediate orthopedic and vascular surgery consultation; admission mandatory for neurovascular observation"}]},"name":"Knee dislocation (vascular assessment, admission)","level":"I","imp":"Knee dislocation","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۲۵ ساله پس از تصادف با دفورمیتی زانو و کاهش نبض پا.","why":"کاهش زودهنگام، ارزیابی عروقی، جراحی عروق."},{"id":"patellar-dislocation-main","o":{"I":[{"t":"Knee radiographs (associated fractures); post-reduction films"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Procedural sedation; analgesia"}],"T":[{"t":"Flex hip and hyperextend knee to slide patella back; knee immobilization"}],"Co":[{"t":"Orthopedic or primary care follow-up"}]},"name":"Patellar dislocation","level":"III","imp":"Patellar dislocation","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"دختر ۱۵ ساله با دفورمیتی زانو حین پیچش، کشکک جانبی.","why":"کاهش با فلکس هیپ و اکستنشن زانو؛ immobilizer."}],"ch":"174","name":"Knee and patellar dislocation","name_fa":"دررفتگی زانو و کشکک","cc":["limb-injury","trauma-major"],"keywords":"knee dislocation, patellar dislocation, popliteal artery injury, ankle-brachial index, peroneal nerve, دررفتگی زانو, شریان پوپلیتئال","status":"draft","features":["کشکک: درد و دفورمیتی؛ پارگی کپسول مدیال ممکن","زانو: اختلال شدید لیگامانی و کپسولی؛ 50% خودبه‌خود جا می‌رود؛ ناپایداری چندجهته ← شک؛ آسیب پوپلیتئال و peroneal شایع","گرافی برای رد شکستگی؛ برخی آنژیوگرافی برای همه؛ دیگران ABI و معاینات سریال اگر نبض دیستال و بدون ایسکمی/خونریزی/هماتوم","sedation؛ کشکک: فلکس هیپ و hyperextension زانو؛ immobilizer و پیگیری؛ زانو: کاهش زودهنگام و ثبت نوروواسکولار قبل و بعد، اسپلینت 20° فلکسیون، مشاوره فوری ارتوپدی و جراحی عروق، بستری اجباری"],"ddx":[{"n":"Popliteal artery injury |","cm":1},{"n":"Tibial plateau / femoral condyle fracture |","cm":1},{"n":"Ligamentous injury |"}],"redflags":["نبض مختل، ایسکمی، ناپایداری چندجهته"],"guide":"زانو دررفته = اورژانس عروقی: ABI/آنژیو، بستری برای پایش.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 174: Knee and Leg Injuries, pp. 956–960"},"knee-tendon-ligament-meniscal":{"id":"knee-tendon-ligament-meniscal","variants":[{"id":"knee-ligament-meniscal-main","o":{"I":[{"t":"Knee radiographs (effusion, Segond fracture, high-riding patella); ultrasound or MRI for Achilles rupture when unclear; outpatient MRI"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Knee immobilization, ice, elevation; locked knee: procedural sedation if needed, supine with knee flexed 90° over bed edge, longitudinal traction with internal and external rotation; Achilles rupture: splint in plantar flexion, non-weight-bearing"}],"Co":[{"t":"Orthopedic referral; patellar / quadriceps tendon rupture: surgical repair within 7–10 days; failed locked-knee reduction: orthopedic consultation"}]},"name":"Knee ligament / meniscal injury / tendon rupture","level":"III","imp":"Knee ligament / meniscal injury","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۸ ساله فوتبالیست با «pop»، تورم زانو و Lachman مثبت.","why":"بالینی؛ immobilizer و ارجاع."}],"ch":"174","name":"Knee tendon, ligament and meniscal injuries; Achilles tendon rupture","name_fa":"آسیب تاندون، لیگامان و منیسک زانو؛ پارگی تاندون آشیل","cc":["limb-injury","joint-limb-pain"],"keywords":"ACL tear, PCL, collateral ligament, meniscal tear, locked knee, Lachman, Thompson test, Achilles tendon rupture, patellar tendon rupture, Segond fracture, پارگی ACL, منیسک, آشیل, تاندون","status":"draft","features":["پارگی تاندون چهارسر/کشککی: درد، تورم، ناتوان در extension در برابر مقاومت، defect قابل‌لمس؛ کشکک high-riding در لترال گرافی","آشیل: درد شدید ساق، ناتوان در toe walk، دویدن، پله؛ defect 2–6 cm بالای کالکانئوس؛ Thompson مثبت (دمر، زانو 90°، فشار ساق ← عدم پلانتارفلکسیون)؛ سونوگرافی یا MRI در مبهم","لیگامان: اغلب هموآرتروز؛ ACL: \"pop\" و تورم طی ساعات؛ Lachman حساس‌ترین؛ drawer قدامی و pivot shift؛ PCL: drawer خلفی؛ MCL/LCL: استرس valgus/varus در 30° فلکسیون؛ لقی > 1 cm بدون firm end point = پارگی کامل؛ تکرار در extension (لقی ← کروسیت و کپسول خلفی)؛ peroneal در آسیب لترال؛ Segond ← ACL","منیسک: قفل شدن دردناک، pop/click، ناپایداری؛ McMurray حساس نیست؛ \"locked knee\": ROM فعال/غیرفعال غیرممکن با درد","تشخیص عمدتاً بالینی؛ MRI یا آرتروسکوپی سرپایی قطعی","درمان: پارگی چهارسر/کشککی: immobilizer و مشاوره جراحی (7–10 روز)؛ آشیل: اسپلینت در پلانتارفلکسیون، non-weight-bearing، ارتوپدی؛ لیگامان/منیسک: immobilizer، یخ، elevation، ضددرد، ارجاع؛ locked knee: ضددرد و کاهش بسته (supine با زانو 90° روی لبه تخت؛ کشش طولی همراه چرخش داخلی و خارجی)؛ مشاوره ارتوپدی در ناموفق"],"ddx":[{"n":"Knee dislocation (spontaneously reduced) |","cm":1},{"n":"Fracture (Segond, tibial spine) |"},{"n":"Septic arthritis / hemarthrosis |"}],"redflags":["ناپایداری چندجهته، locked knee، نبض مختل"],"guide":"Immobilizer، یخ، elevation، ضددرد، ارجاع.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 174: Knee and Leg Injuries, pp. 956–960"},"knee-leg-overuse":{"id":"knee-leg-overuse","variants":[{"id":"knee-leg-overuse-main","o":{"I":[{"t":"Radiographs often normal; outpatient bone scan or MRI if stress fracture suspected"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"NSAIDs"}],"T":[{"t":"Heat; quadriceps-strengthening exercises (patellar tendonitis); avoid steroid injections; discontinue the activity for several weeks (shin splints, stress fracture)"}],"Co":[{"t":"Outpatient follow-up"}]},"name":"Overuse injury — knee / leg","level":"III","imp":"Patellar tendonitis / shin splints / stress fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"دونده ۲۰ ساله با درد قدام ساق پس از افزایش ناگهانی مسافت.","why":"قطع فعالیت."}],"ch":"174","name":"Overuse injuries of the knee and leg (patellar tendonitis, shin splints, stress fracture)","name_fa":"آسیب‌های overuse زانو و ساق (تاندونیت کشککی، shin splints، شکستگی استرس)","cc":["limb-injury","joint-limb-pain"],"keywords":"patellar tendonitis, jumper knee, shin splints, stress fracture, تاندونیت کشککی, شکستگی استرسی","status":"draft","features":["تاندونیت کشککی (jumper's knee): درد روی تاندون با دویدن در سربالایی، پرش یا برخاستن؛ گرم، NSAID، تقویت چهارسر؛ از تزریق استروئید پرهیز","Shin splints و شکستگی استرسی: درد قدام ساق؛ افزایش ناگهانی تمرین؛ درد با فعالیت و بهبود با استراحت، ممکن پیشرونده؛ گرافی غالباً طبیعی","درمان: قطع فعالیت چند هفته؛ شک شکستگی استرسی: bone scan یا MRI سرپایی"],"ddx":[{"n":"Stress fracture |"},{"n":"Compartment syndrome (exertional) |"}],"redflags":["ندارد (خوش‌خیم)"],"guide":"قطع فعالیت چند هفته، NSAID، تقویت چهارسر.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 174: Knee and Leg Injuries, pp. 956–960"},"ankle-sprain-tendon":{"id":"ankle-sprain-tendon","variants":[{"id":"ankle-sprain-stable","o":{"I":[{"t":"Ankle radiographs only if Ottawa Ankle Rules positive"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesics"}],"T":[{"t":"Elastic bandage or ankle brace, rest, ice, compression, elevation (PRICE) up to 72 hours; motion and strength exercises within 48–72 hours"}],"Co":[{"t":"Orthopedic follow-up if pain persists beyond one week"}]},"name":"Ankle sprain — stable joint, able to bear weight","level":"III","imp":"Ankle sprain","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله پس از پیچ‌خوردگی مچ، تورم خفیف، قادر به راه رفتن.","why":"Ottawa rule و PRICE."},{"id":"ankle-sprain-unstable","o":{"I":[{"t":"Ankle radiographs including mortise / talus views (symmetry of talar-malleolar gap), fibula films for Maisonneuve; ultrasound or MRI if Achilles diagnosis unclear"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesics"}],"T":[{"t":"Unstable joint: posterior splint, crutches; unable to bear weight: ankle brace, crutches; Achilles rupture: splint in plantar flexion, nonweightbearing with crutches"}],"Co":[{"t":"Timely orthopedic referral (Achilles: early referral for possible operative repair)"}]},"name":"Ankle sprain — unstable joint / unable to bear weight / Achilles tendon rupture","level":"II","imp":"Unstable ankle sprain / Achilles tendon rupture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۴۵ ساله حین ورزش با «pop» پشت پاشنه و Thompson مثبت.","why":"splint در plantarflexion، non-weight-bearing."}],"ch":"175","name":"Ankle sprain / ligament injury and Achilles tendon rupture","name_fa":"رگ‌به‌رگ‌شدگی مچ پا / آسیب لیگامان و پارگی تاندون آشیل","cc":["limb-injury","joint-limb-pain"],"keywords":"ankle sprain, Ottawa ankle rules, Achilles tendon rupture, Thompson test, syndesmosis, Maisonneuve, anterior drawer, talar tilt, PRICE, پیچ‌خوردگی مچ پا, قوانین اتاوا, آشیل","status":"draft","features":["تاندون: peroneal (hyperdorsiflexion)، آشیل (plantarflexion ناگهانی)؛ آشیل: درد شدید، ناتوان در toe walk، دویدن، پله؛ Thompson مثبت","رگ‌به‌رگ‌شدگی: inversion / eversion؛ شایع‌ترین: anterior talofibular؛ دلتوئید مدیال نادر و مرتبط با Maisonneuve یا syndesmosis","معاینه: مفاصل بالا و پایین؛ تندرنس فیبولای پروگزیمال، squeeze test (سندسموز)، تندرنس خلف مالئول لترال ← subluxation تاندون peroneal","Ottawa Ankle Rules (شکل 175-1): گرافی فقط اگر درد ناحیه مالئولار یا میدفوت + تندرنس استخوانی در یکی از 4 نقطه (لبه خلفی/نوک مالئول لترال، مدیال، قاعده متاتارس پنجم، navicular) یا ناتوان در تحمل وزن (فوراً و در ED)","ثبات: anterior drawer، talar tilt؛ استرس تست ناممکن = بالقوه ناپایدار؛ عدم تقارن فاصله talar dome و مالئول در گرافی = ناپایدار","جدول 175-1: Maisonneuve، peroneal subluxation، osteochondral، syndesmosis tear، شکستگی anterior calcaneal process، lateral talar process، os trigonum"],"ddx":[{"n":"Fracture (ankle / fifth metatarsal / Maisonneuve) |","cm":1},{"n":"Neurovascular compromise |","cm":1},{"n":"Achilles tendon rupture |"},{"n":"Syndesmosis injury |"}],"redflags":["نبض مختل، ناپایداری مفصل، Thompson مثبت"],"guide":"1) Ottawa rules. 2) مفصل پایدار و قادر تحمل وزن: elastic bandage یا ankle brace، PRICE تا 72 ساعت، ضددرد، ورزش حرکتی در 48–72 ساعت؛ درد > 1 هفته: ارتوپدی. 3) پایدار ولی ناتوان در تحمل وزن: brace، crutches، ارتوپدی. 4) ناپایدار: posterior splint، crutches، ارجاع به‌موقع. 5) آشیل: splint در plantar flexion، crutches non-weightbearing، ارجاع زودرس.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 175: Ankle and Foot Injuries, pp. 961–965"},"ankle-dislocation-fracture":{"id":"ankle-dislocation-fracture","variants":[{"id":"ankle-dislocation-main","o":{"I":[{"t":"Ankle radiographs (AP, lateral, mortise) before and after reduction"}],"L":[{"t":"Type and screen, coagulation studies"}],"S":[{"t":"Analgesia and procedural sedation"}],"A":[{"t":"Open fracture: cefazolin 1 g IV (first-generation cephalosporin)","fl":[{"k":"ci","v":"cephalosporin allergy"}]}],"T":[{"t":"Reduce immediately if vascular compromise or skin tenting (heel and foot grasped, axial traction); wet sterile dressing and splint for open fracture; tetanus toxoid as necessary; post-reduction neurovascular check; posterior splint; elevation, ice"}],"Co":[{"t":"Immediate orthopedic consultation"}]},"name":"Ankle dislocation / open fracture (immediate reduction, consult)","level":"I","imp":"Ankle dislocation / open ankle fracture","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زن ۳۵ ساله پس از سقوط با دفورمیتی مچ، پای تیره و نبض ضعیف.","why":"کاهش فوری و مشاوره."},{"id":"ankle-fracture-closed","o":{"I":[{"t":"Ankle radiographs (AP, lateral, mortise); CT for suspected occult injury"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"T":[{"t":"Reduce as needed; posterior splint; elevation; ice; nonweightbearing; minimally displaced avulsion fibular fractures (< 3 mm) managed like sprains"}],"Co":[{"t":"Orthopedic consultation (bimalleolar / trimalleolar: ORIF); unimalleolar: non-weightbearing and posterior splint"}]},"name":"Closed ankle fracture (uni-, bi-, trimalleolar)","level":"II","imp":"Closed ankle fracture","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زن ۵۰ ساله پس از لغزش با تورم و درد مالئول لترال و ناتوان در تحمل وزن.","why":"گرافی؛ bi/tri مالئولار ← ORIF."}],"ch":"175","name":"Ankle dislocation and ankle fractures (uni-, bi-, trimalleolar, open)","name_fa":"دررفتگی و شکستگی مچ پا (یک، دو، سه مالئول، باز)","cc":["limb-injury","trauma-major"],"keywords":"ankle dislocation, bimalleolar fracture, trimalleolar fracture, open ankle fracture, posterior splint, ORIF, دررفتگی مچ پا, شکستگی مچ","status":"draft","features":["دررفتگی خلفی: شایع‌ترین؛ نیروی عقب روی پای plantarflexed؛ پارگی tibiofibular یا شکستگی لترال مالئول","کاهش فوری اگر مختل شدن عروق (نبض غایب یا پای تیره) یا skin tenting: ضددرد/sedation؛ پاشنه و پا با دو دست، کشش axial و هم‌راستاسازی؛ پس از کاهش: وضعیت نوروواسکولار، splint، گرافی، مشاوره فوری ارتوپدی","شکستگی: unimalleolar، bimalleolar، trimalleolar؛ bi- و tri- نیاز ORIF؛ ED: کاهش، posterior splint، elevation، یخ، مشاوره","unimalleolar: non-weightbearing و posterior splint؛ avulsion فیبولا < 3 mm مثل سالنج","باز: کاهش اولیه، پانسمان استریل مرطوب، splint، کزاز، cefazolin 1 g IV، مشاوره فوری ارتوپدی","ممکن occult (جدول 175-1)"],"ddx":[{"n":"Vascular compromise |","cm":1},{"n":"Open fracture |","cm":1},{"n":"Maisonneuve fracture |"},{"n":"Syndesmosis tear |"}],"redflags":["پای تیره/نبض غایب، skin tenting، شکستگی باز"],"guide":"دررفتگی با اختلال عروقی: کاهش فوری. باز: cefazolin 1 g IV و مشاوره فوری.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 175: Ankle and Foot Injuries, pp. 961–965"},"foot-injuries":{"id":"foot-injuries","variants":[{"id":"foot-injury-major","o":{"I":[{"t":"Foot radiographs including lateral (Boehler angle < 20° suggests calcaneal fracture); CT for talus, Lisfranc and subtle findings"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesia"}],"A":[{"t":"Open fractures of any kind: consider antibiotics, tetanus (Td)"}],"T":[{"t":"Posterior splint (well padded), elevation, non-weightbearing, RICE"}],"Co":[{"t":"Immediate orthopedic consultation (intra-articular calcaneal, major talus, subtalar dislocation, Lisfranc, open fractures in ED); early referral for minor injuries (within 2 weeks)"}]},"name":"Major foot injury — calcaneus / talus / Lisfranc / open fracture","level":"II","imp":"Major foot fracture (calcaneus / talus / Lisfranc)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله پس از سقوط از ارتفاع با درد پاشنه و ناتوانی در تحمل وزن.","why":"گرافی/CT، splint، مشاوره."},{"id":"foot-injury-minor","o":{"I":[{"t":"Foot radiographs (base of fifth metatarsal, base of second metatarsal); plain films or CT for athletes / Lisfranc concern"}],"L":[{"t":"Not routinely required beyond fixed set"}],"S":[{"t":"Analgesics"}],"T":[{"t":"Nondisplaced metatarsal shaft: posterior splint or orthopedic shoe; pseudo-Jones: walking cast; true Jones: nonweightbearing cast; nondisplaced phalanx: buddy taping and stiff-sole shoe; displaced phalanx / dislocation: digital block, manual traction reduction, buddy taping; stress fracture: cessation of activity"}],"Co":[{"t":"Orthopedic follow-up (true Jones within a week for a cast; metatarsal > 3–4 mm displacement needs surgical reduction)"}]},"name":"Forefoot injury — metatarsal / Jones / toe fracture","level":"III","imp":"Metatarsal / phalanx fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۰ ساله با درد کنار خارجی پا پس از پیچ خوردن؛ تندرنس قاعده متاتارس پنجم.","why":"تشخیص pseudo-Jones یا Jones و درمان مناسب."}],"ch":"175","name":"Foot injuries (calcaneus, talus, Lisfranc, metatarsal / Jones, phalanx)","name_fa":"آسیب‌های پا (کالکانئوس، تالوس، Lisfranc، متاتارس / Jones، فالانکس)","cc":["limb-injury","joint-limb-pain"],"keywords":"calcaneal fracture, Boehler angle, talus fracture, Lisfranc injury, Jones fracture, metatarsal fracture, toe fracture, stress fracture, navicular, cuboid, شکستگی کالکانئوس, لیسفرانک, جونز","status":"draft","features":["ناحیه‌ها: hindfoot، midfoot (مفصل Chopart)، forefoot (مفصل Lisfranc)؛ توجه به قاعده متاتارس پنجم و دوم؛ اگر گرافی ناتشخیصی ← CT برای Lisfranc","کالکانئوس: نیروی زیاد، آسیب‌های همراه؛ زاویه Boehler (لترال) < 20° ← شکستگی؛ posterior splint، elevation، ضددرد، مشاوره؛ avulsion کوچک تالوس: posterior splint و ارجاع؛ subtalar dislocation و شکستگی ماژور گردن/بدنه تالوس: مشاوره فوری","Lisfranc: درد TMT با پیچش میدفوت؛ شکستگی قاعده متاتارس دوم؛ فاصله > 1 mm بین قاعده متاتارس 1 و 2 = ناپایدار؛ CT اگر گرافی ناتشخیصی؛ navicular/cuboid/cuneiform ایزوله نادر و محافظه‌کارانه","متاتارس شفت بدون جابه‌جایی: posterior splint یا کفش ارتوپدی؛ > 3–4 mm جابه‌جایی: جراحی؛ pseudo-Jones (avulsion tuberosity متاتارس پنجم): walking cast؛ true Jones (اتصال متافیز-دیافیز پنجم): non-weightbearing cast و ارجاع (احتمال جراحی)؛ فالانکس بدون جابه‌جایی: buddy taping و کفش سخت؛ جابه‌جایی‌دار/دررفتگی: digital block، کشش دستی، buddy taping","جدول 175-2: calcaneal (plain، Boehler، CT؛ NWBS، RICE؛ intra-articular فوری، extra-articular زودرس)؛ talus (CT؛ خطر AVN)؛ Lisfranc (CT؛ splint؛ فوری)؛ navicular/cuboid/cuneiform (plain یا CT؛ splint)؛ Jones؛ stress fracture (قطع فعالیت؛ ورزشکار: احتمال جراحی)؛ باز: ارتوپدی در ED، پیشنهاد آنتی‌بیوتیک و Td"],"ddx":[{"n":"Compartment syndrome (calcaneal) |","cm":1},{"n":"Lisfranc injury (missed) |","cm":1},{"n":"Open fracture |","cm":1},{"n":"Ankle injury |"}],"redflags":["Lisfranc، talus، calcaneus با نیروی زیاد، شکستگی باز، اختلال عروقی"],"guide":"جدول 175-2: همه بیماران آنالژزی کافی؛ splint کافی padding؛ NWBS و RICE.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 175: Ankle and Foot Injuries, pp. 961–965"},"compartment-syndrome":{"id":"compartment-syndrome","variants":[{"id":"compartment-syndrome-main","o":{"I":[{"t":"Compartment pressure measurement if diagnosis in doubt or obtunded / sedated patient (normal < 10 mmHg; delta pressure ≤ 30 mmHg); radiographs for associated fracture"}],"L":[{"t":"Coagulation studies (anticoagulated patients: reverse; hemophilia: factor levels)"}],"S":[{"t":"Analgesia; correct hypotension"}],"T":[{"t":"Supplemental oxygen; remove constrictive casts or dressings; place affected limb at level of the heart; reverse anticoagulation in anticoagulated patients, replace factor levels in hemophiliacs; NPO for surgery"}],"Co":[{"t":"Emergent surgical fasciotomy (orthopedics / trauma / vascular); admit to operating room or inpatient service for serial examinations"}]},"name":"Compartment syndrome (fasciotomy)","level":"I","imp":"Compartment syndrome","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","o2":"Supplemental oxygen","sc":"مرد ۲۵ ساله پس از شکستگی تیبیا با درد غیرقابل‌کنترل ساق، درد با کشش پاسیو و کمپارتمان سفت.","why":"فاسیوتومی؛ تأخیر > 6 ساعت = پیامد بد."}],"ch":"176","name":"Compartment syndrome","name_fa":"سندرم کمپارتمان","cc":["limb-injury","joint-limb-pain","trauma-major"],"keywords":"compartment syndrome, fasciotomy, compartment pressure, delta pressure, pain with passive stretch, tibial fracture, crush injury, سندرم کمپارتمان, فاسیوتومی, فشار کمپارتمان","status":"draft","features":["فشار بالا در کمپارتمان عضلانی ← اختلال عملکرد و گردش؛ شایع‌ترین: ساق و ساعد؛ علل (جدول 176-1): ارتوپدیک (شکستگی تیبیا و ساعد)، عروقی (ischemia-reperfusion، خونریزی)، iatrogenic (پانکچر عروق در anticoagulated، تزریق IV/intra-arterial، گچ محدودکننده)، نسج نرم (فشار طولانی، crush، سوختگی)، هماتولوژیک (هموفیلی، وارفارین)","درد شدید و مشکل‌کنترل، درد خارج از تناسب، درد با کشش پاسیو؛ اختلال عصبی (سوزش/دیزستزی)؛ ضعف حرکتی؛ کمپارتمان متورم، سفت، تندر","نبض دیستال، دما و رنگ اغلب طبیعی (فشار بافتی معمولاً از فشار شریانی بیشتر نمی‌شود)؛ شروع چند ساعت تا 48 ساعت پس از آسیب","تشخیص عمدتاً بالینی؛ اندازه‌گیری مستقیم فشار در شک یا بیمار obtunded/sedated؛ طبیعی < 10 mmHg؛ 30–50 mmHg مضر اگر ساعت‌ها؛ delta pressure (diastolic − tissue) ≤ 30 mmHg تشخیصی؛ هیپوتانسیو تحمل کمتر","پیامد خوب اگر تشخیص و درمان < 6 ساعت؛ فاسیوتومی پس از 24–48 ساعت ممکن بی‌اثر"],"ddx":[{"n":"Fracture / hematoma / infection |","cm":1},{"n":"Arterial occlusion |","cm":1},{"n":"Nerve injury |"}],"redflags":["درد خارج از تناسب، درد با کشش پاسیو، کمپارتمان سفت و متورم"],"guide":"تأیید ← فاسیوتومی جراحی؛ بستری OR یا inpatient با معاینات سریال. تا زمان تعیین‌تکلیف: O2 مکمل، اصلاح هیپوتانسیون، برداشتن گچ/پانسمان محدودکننده، قرار دادن اندام در سطح قلب؛ برگرداندن anticoagulation و جایگزینی فاکتور در هموفیلی.","section":"bones-joints","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 176: Compartment Syndrome, pp. 966–968"}});
